/* Greek Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Nikolaos": "victory of the people — Greek nike + laos", "Maria": "The most common Greek feminine name.", "Georgios": "farmer, earthworker — Greek georgos", "Eleni": "torch, light — Greek helene", "Dimitrios": "of Demeter — Greek", "Katerina": "pure — Greek katharos", "Papadopoulos": "The most famous Greek surname form.", "Nikolaidis": "A classic -idis patronymic.", "Georgiou": "A genitive-form surname.", "Papandreou": "The family name of Greek prime ministers."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Nikolaos';
console.log(lookup(q));

